import { promises as fs } from 'node:fs';
import * as path from 'node:path';

export interface ModuleRegistrySnapshot {
  modules: ModuleDefinition[];
}

export interface ModuleDefinition {
  id: string;
  name: string;
  categories?: ModuleCategory[];
}

export interface ModuleCategory {
  title: string;
  options?: ModuleOption[];
}

export interface ModuleOption {
  key: string;
  type: string;
  default: unknown;
}

let cachedModulesPath = '';
let cachedModules: ModuleDefinition[] | null = null;

function snapshotPath(rootDir: string): string {
  return path.join(rootDir, 'backend_ts', 'src', 'generated', 'modules.json');
}

async function loadModules(rootDir: string): Promise<ModuleDefinition[]> {
  const nextPath = snapshotPath(rootDir);
  if (cachedModules && cachedModulesPath === nextPath) {
    return cachedModules;
  }

  const text = await fs.readFile(nextPath, 'utf8');
  const parsed = JSON.parse(text) as Partial<ModuleRegistrySnapshot>;
  if (!Array.isArray(parsed.modules)) {
    throw new Error(`Invalid module registry snapshot: ${nextPath}`);
  }

  cachedModulesPath = nextPath;
  cachedModules = parsed.modules as ModuleDefinition[];
  return cachedModules;
}

export async function listModules(rootDir: string): Promise<ModuleDefinition[]> {
  return await loadModules(rootDir);
}

export async function getModule(rootDir: string, moduleId: string): Promise<ModuleDefinition | null> {
  const modules = await loadModules(rootDir);
  return modules.find((module) => module.id === moduleId) ?? null;
}

function normaliseValue(option: ModuleOption, value: unknown): boolean | number | string {
  if (option.type === 'bool') {
    return Boolean(value);
  }
  if (option.type === 'int') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : Number(option.default ?? 0);
  }
  return String(value ?? option.default ?? '');
}

function formatKconfig(option: ModuleOption, value: unknown): string {
  if (option.type === 'bool') {
    return `${option.key}=${value ? 'y' : 'n'}`;
  }
  return `${option.key}=${String(value)}`;
}

export async function generateModuleConfig(
  rootDir: string,
  modulesMap: Record<string, Record<string, unknown>>,
): Promise<{ prj_conf: string; overlay_conf: string }> {
  const linesPrj = [
    '# --- Zephyr module configuration --------------------------------',
    '# Generated by Zephyr Module Configurator',
    '',
  ];
  const linesOverlay = [
    '# --- Zephyr full overlay configuration ---------------------------',
    '# Generated by Zephyr Module Configurator',
    '',
  ];

  for (const [moduleId, values] of Object.entries(modulesMap)) {
    const module = await getModule(rootDir, moduleId);
    if (!module) {
      continue;
    }

    const categories = module.categories ?? [];
    let masterKey: string | null = null;
    if (categories[0]?.options?.[0]?.type === 'bool' && categories[0].options[0].key) {
      masterKey = categories[0].options[0].key;
    }

    linesPrj.push(`# -- ${module.name} ${'-'.repeat(Math.max(1, 52 - module.name.length))}`);
    for (const category of categories) {
      const categoryLines: string[] = [];
      for (const option of category.options ?? []) {
        const currentValue = normaliseValue(option, values[option.key] ?? option.default);
        const defaultValue = option.default;

        if (currentValue !== defaultValue) {
          categoryLines.push(formatKconfig(option, currentValue));
        } else if (option.key === masterKey && currentValue) {
          categoryLines.push(`${option.key}=y`);
        }
      }

      if (categoryLines.length > 0) {
        linesPrj.push(`# ${category.title}`);
        linesPrj.push(...categoryLines);
      }
    }
    linesPrj.push('');

    linesOverlay.push(`# -- ${module.name} ${'-'.repeat(Math.max(1, 52 - module.name.length))}`);
    for (const category of categories) {
      linesOverlay.push(`# ${category.title}`);
      for (const option of category.options ?? []) {
        const currentValue = normaliseValue(option, values[option.key] ?? option.default);
        linesOverlay.push(formatKconfig(option, currentValue));
      }
    }
    linesOverlay.push('');
  }

  return {
    prj_conf: linesPrj.join('\n'),
    overlay_conf: linesOverlay.join('\n'),
  };
}